<script setup lang="ts">
interface FailureRow { failure_id: number; task_id: string; stage: string; summary: string; raw_error: string | null; attempt: number | null; created_at: string; legal_actions: string[] }
const { data, error } = await useFetch<{ failures: FailureRow[] }>('/api/errors')
async function copy(value: unknown) { await navigator.clipboard.writeText(typeof value === 'string' ? value : JSON.stringify(value, null, 2)) }
</script>
<template><main class="space-y-5"><div><p class="text-xs font-bold uppercase tracking-widest text-fg-muted">Recovery</p><h1 class="mt-2 text-3xl font-black">Error center</h1></div><p v-if="error" class="text-danger">{{ error.message }}</p><p v-if="!data?.failures.length" class="rounded-card border border-[var(--bs-border)] bg-surface p-6 text-fg-muted">No unresolved structured failures.</p><article v-for="failure in data?.failures || []" :key="failure.failure_id" class="rounded-card border border-danger/30 bg-surface p-5"><div class="flex flex-wrap justify-between gap-2"><div><DashboardStatusPill value="failed" /><h2 class="mt-2 font-black">{{ failure.task_id }} · {{ failure.stage }}</h2><p class="mt-1 text-sm text-fg-muted">{{ failure.summary }}</p></div><div class="text-end text-xs text-fg-muted"><p>Attempt {{ failure.attempt ?? '—' }}</p><p>{{ failure.created_at }}</p></div></div><div class="mt-4 flex flex-wrap gap-2"><button class="rounded-control border border-[var(--bs-border)] px-3 py-2 text-xs font-bold" @click="copy(failure.raw_error || failure.summary)">Copy Error</button><button class="rounded-control border border-[var(--bs-border)] px-3 py-2 text-xs font-bold" @click="copy(failure)">Copy Diagnostic Bundle</button><NuxtLink class="rounded-control border border-[var(--bs-border)] px-3 py-2 text-xs font-bold text-link" :to="`/tasks/${failure.task_id}`">Open task</NuxtLink></div><p class="mt-3 text-xs text-fg-muted">Legal actions: {{ (failure.legal_actions || []).join(', ') || 'inspect' }}</p></article></main></template>
